/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/alert.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
import * as React from "react";
import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
const alertVariants = cva("relative grid w-full grid-cols-[0_1fr] items-start gap-y-0.5 rounded-lg border px-4 py-3 text-sm has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg]:gap-x-3 [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current", {
  variants: {
    variant: {
      default: "bg-card text-card-foreground",
      destructive: "bg-card text-destructive *:data-[slot=alert-description]:text-destructive/90 [&>svg]:text-current"
    }
  },
  defaultVariants: {
    variant: "default"
  }
});
function Alert({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants> & CapconsBasePropsLoose) {
  return <div data-slot="alert" role="alert" className={cn(alertVariants({
    variant
  }), className)} {...capconsSpread(props)} />;
}
function AlertTitle({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="alert-title" className={cn("col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight", className)} {...capconsSpread(props)} />;
}
function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="alert-description" className={cn("col-start-2 grid justify-items-start gap-1 text-sm text-muted-foreground [&_p]:leading-relaxed", className)} {...capconsSpread(props)} />;
}
export { Alert, AlertTitle, AlertDescription };
